def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "grab_pan": And([
            self.pan_is_hot,  # Pan is hot
            Not(self.robot_equipped_with_pad),  # No heat-resistant pad
            self.infrared_sensor_enabled  # Sensor is available
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
